{
  "schema_version": 1,
  "name": "cand_test1",
  "summary": "Listener choice and target probability rating across multi-scale scenes.",
  "charter": {
    "question": "How do people combine contextual distinctiveness, feature complexity, and pragmatic alternatives when choosing and rating candidate referents across varying display sizes?"
  },
  "instructions": {
    "welcome": "Welcome to our study on how people understand descriptions of objects.",
    "task": "In each round, you will see a row of objects that differ in their parts. A speaker sees the same objects and wants to point out one of them. On most rounds, the speaker says a single word that is true of the object they mean. On some rounds, you have not heard the speaker's word yet. Your task is to click the object you think the speaker means.",
    "comprehension_checks": [
      {
        "question": "What is your task on each round?",
        "options": [
          "Click the single object you think the speaker is referring to.",
          "Click every object that has the named part.",
          "Write a description of all the objects."
        ],
        "correct": 0
      }
    ]
